<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Assistant;
use App\Domain\Assistant\Entity\AssistantConversation;use App\Domain\Assistant\Entity\AssistantMessage;use App\Domain\Assistant\Repository\AssistantConversationRepositoryInterface;use App\Domain\Assistant\ValueObject\SyllabusEvidence;use App\Infrastructure\Persistence\Doctrine\Assistant\Entity\AssistantConversationRecord;use App\Infrastructure\Persistence\Doctrine\Assistant\Entity\AssistantMessageRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineAssistantConversationRepository implements AssistantConversationRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function saveConversation(AssistantConversation $c):void{$r=$this->entityManager->find(AssistantConversationRecord::class,$c->id)??new AssistantConversationRecord();$r->id=$c->id;$r->userId=$c->userId;$r->syllabusId=$c->syllabusId;$r->title=$c->title;$r->createdAt=$c->createdAt;$r->updatedAt=$c->updatedAt;$this->entityManager->persist($r);} public function findConversationForUser(string $id,string $userId):?AssistantConversation{$r=$this->entityManager->createQueryBuilder()->select('c')->from(AssistantConversationRecord::class,'c')->where('c.id=:id')->andWhere('c.userId=:user')->setParameters(['id'=>$id,'user'=>$userId])->getQuery()->getOneOrNullResult();return $r instanceof AssistantConversationRecord?$this->conversation($r):null;} public function listConversationsForUser(string $userId):array{return array_map($this->conversation(...),$this->entityManager->createQueryBuilder()->select('c')->from(AssistantConversationRecord::class,'c')->where('c.userId=:user')->setParameter('user',$userId)->orderBy('c.updatedAt','DESC')->getQuery()->getResult());} public function saveMessage(AssistantMessage $m):void{$r=new AssistantMessageRecord();$r->id=$m->id;$r->conversationId=$m->conversationId;$r->role=$m->role;$r->content=$m->content;$r->provider=$m->provider;$r->model=$m->model;$r->evidenceJson=array_map(static fn(SyllabusEvidence $e)=>['pageNumber'=>$e->pageNumber,'excerpt'=>$e->excerpt],$m->evidence);$r->createdAt=$m->createdAt;$this->entityManager->persist($r);$c=$this->entityManager->find(AssistantConversationRecord::class,$m->conversationId);if($c instanceof AssistantConversationRecord)$c->updatedAt=$m->createdAt;} public function listMessagesForConversation(string $conversationId):array{return array_map($this->message(...),$this->entityManager->createQueryBuilder()->select('m')->from(AssistantMessageRecord::class,'m')->where('m.conversationId=:id')->setParameter('id',$conversationId)->orderBy('m.createdAt','ASC')->getQuery()->getResult());} private function conversation(AssistantConversationRecord $r):AssistantConversation{return new AssistantConversation($r->id,$r->userId,$r->syllabusId,$r->title,$r->createdAt,$r->updatedAt);} private function message(AssistantMessageRecord $r):AssistantMessage{return new AssistantMessage($r->id,$r->conversationId,$r->role,$r->content,$r->provider,$r->model,array_map(static fn(array $e)=>new SyllabusEvidence((int)$e['pageNumber'],(string)$e['excerpt']),$r->evidenceJson??[]),$r->createdAt);} }
